from functools import lru_cache
from itertools import combinations

def canon(fs):
    return tuple(sorted(set(fs)))

def subsets_bounded(mask, bound):
    v = [1 << i for i in range(mask.bit_length()) if mask >> i & 1]
    for s in range(1, min(bound, len(v)) + 1):
        for c in combinations(v, s):
            yield sum(c)

@lru_cache(None)
def shellable(fs):
    if len(fs) == 1:
        return True
    m = fs[0].bit_count()
    for f in fs:
        rest = tuple(g for g in fs if g != f)
        intersections = {f & g for g in rest}
        # Intersection must be generated by codimension-one faces.
        ridges = [h for h in intersections if h.bit_count() == m - 1]
        if all(any(h & r == h for r in ridges) for h in intersections):
            if shellable(rest):
                return True
    return False

@lru_cache(None)
def kdec(fs, k):
    if len(fs) == 1:
        return True
    candidates = set()
    for f in fs:
        candidates.update(subsets_bounded(f, k + 1))
    for s in candidates:
        rest = tuple(f for f in fs if f & s != s)
        if not rest:
            continue
        containing = tuple(f for f in fs if f & s == s)
        # Maximal possible residual faces after deleting s are f - {v}, v in s.
        residuals = [f ^ v for f in containing
                     for v in subsets_bounded(s, 1)]
        if not all(any(h & g == h for g in rest) for h in residuals):
            continue
        link = canon(f ^ s for f in containing)
        if kdec(rest, k) and kdec(link, k):
            return True
    return False

def check(n, d):
    facets = [sum(1 << i for i in c) for c in combinations(range(n), d+1)]
    N = len(facets)
    good = set()
    for mask in range(1, 1 << N):
        fs = canon(facets[j] for j in range(N) if mask >> j & 1)
        sh = shellable(fs)
        assert sh == kdec(fs, d), (n, d, mask)
        if sh:
            good.add(mask)
    full = (1 << N) - 1
    extendable = {full}
    for mask in sorted(good, key=int.bit_count, reverse=True):
        if any((mask | (1 << j)) in extendable
               for j in range(N) if not (mask >> j & 1)):
            extendable.add(mask)
    assert good == extendable
    print(dict(n=n, d=d, pure_complexes=full,
               shellable_and_d_decomposable=len(good),
               completable_on_same_ground_set=len(extendable)))

if __name__ == '__main__':
    check(5, 2)
    check(6, 3)

